package checkout.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class DiscountPolicy {
    public static int totalCents(int unitCents, int quantity, boolean member) {
        if (unitCents < 0 || quantity < 0) {
            throw new IllegalArgumentException("unitCents and quantity must be nonnegative");
        }
        if (quantity == 0) {
            return 0;
        }

        int discountPercent = member ? 7 : 0;
        if (quantity >= 12) {
            discountPercent += 5;
        }

        BigDecimal subtotal = BigDecimal.valueOf(unitCents).multiply(BigDecimal.valueOf(quantity));
        BigDecimal multiplier = BigDecimal.ONE.subtract(BigDecimal.valueOf(discountPercent).movePointLeft(2));
        BigDecimal total = subtotal.multiply(multiplier).setScale(0, RoundingMode.HALF_EVEN);

        if (total.compareTo(BigDecimal.valueOf(Integer.MAX_VALUE)) > 0) {
            throw new ArithmeticException("total exceeds Integer.MAX_VALUE");
        }
        return total.intValueExact();
    }
}
